import{encounterFromAIAsset}from"./ai-director-adapter.js";
import{isCompatible,rankAssets}from"./semantic-matcher.js";
import{hash,unique}from"./utils.js";

export function findLibraryMatch(profile,assets,threshold=.62){const ranked=rankAssets(profile,assets),best=ranked[0];return{ranked,best:best&&best.score>=threshold?best:null,medium:ranked.filter(x=>x.score>=.42&&x.score<threshold)}}
export function crossoverAssets(a,b,profile,options={}){if(!isCompatible(a,b))return null;const seed=options.seed??hash(`${a.monsterId}|${b.monsterId}|${Date.now()}`),hybrid={...a,monsterId:`cross-${hash(`${a.monsterId}|${b.monsterId}|${seed}`).toString(36)}`,monsterName:Math.random()>.5?a.monsterName:b.monsterName,monsterConcept:`${a.monsterConcept}；融合${b.monsterConcept}`,visualDNA:{metaphor:a.visualDNA?.metaphor||a.visualMetaphor,traits:unique([...(a.visualDNA?.traits||a.visualTraits||[]),...(b.visualDNA?.traits||b.visualTraits||[])]).slice(0,10)},personalityDNA:Math.random()>.5?a.personalityDNA:b.personalityDNA,storyDNA:Math.random()>.5?a.storyDNA:b.storyDNA,combatDNA:{behaviors:unique([...(a.combatDNA?.behaviors||a.combatPersonality||[]),...(b.combatDNA?.behaviors||b.combatPersonality||[])]).slice(0,5)},symbolicArmorDNA:unique([...(a.symbolicArmorDNA||a.symbolicArmor||[]),...(b.symbolicArmorDNA||b.symbolicArmor||[])]).slice(0,3),arenaDNA:Math.random()>.5?a.arenaDNA:b.arenaDNA,dialogueDNA:{intro:unique([...(a.dialogueDNA?.intro||a.introLines||[]),...(b.dialogueDNA?.intro||b.introLines||[])]).slice(0,4),defiant:unique([...(a.dialogueDNA?.defiant||a.defiantLines||[]),...(b.dialogueDNA?.defiant||b.defiantLines||[])]).slice(0,6),cracked:unique([...(a.dialogueDNA?.cracked||a.crackedLines||[]),...(b.dialogueDNA?.cracked||b.crackedLines||[])]).slice(0,6),breakdown:unique([...(a.dialogueDNA?.breakdown||a.breakdownLines||[]),...(b.dialogueDNA?.breakdown||b.breakdownLines||[])]).slice(0,5),ko:unique([...(a.dialogueDNA?.ko||a.koLines||[]),...(b.dialogueDNA?.ko||b.koLines||[])]).slice(0,3)}};const encounter=encounterFromAIAsset(hybrid,profile,{...options,seed,origin:"ai-crossover"});encounter.sourceAssetIds=[a.monsterId,b.monsterId];return encounter}
export class MonsterLibrary{
  constructor(storage){this.storage=storage}
  async search(profile){const assets=await this.storage.getAIAssets();return findLibraryMatch(profile,assets)}
  async reuse(asset,profile,options={}){await this.storage.touchAIAsset(asset.monsterId,{incrementReuse:true});return encounterFromAIAsset(asset,profile,{...options,origin:"ai-library"})}
  async save(asset){return this.storage.putAIAsset(asset)}
}
